13	  const entries = fs.readdirSync(evalsDir).filter(e => e.startsWith("eval-"));
14	  entries.sort((a, b) => {
15	    const idA = parseInt(a.split("-")[1], 10);
16	    const idB = parseInt(b.split("-")[1], 10);
17	    return idA - idB;
18	  });
19	  return entries.map(entry => {
20	    const dir = path.join(evalsDir, entry);
21	    const meta = JSON.parse(fs.readFileSync(path.join(dir, "eval.json"), "utf-8"));
22	    meta.prompt = fs.readFileSync(path.join(dir, "prompt.md"), "utf-8").replace(/\n$/, "");
23	    meta.expected_output = fs.readFileSync(path.join(dir, "expected_output.md"), "utf-8").replace(/\n$/, "");
24	    return meta;
25	  });
